function validate([deck]) {
  if (!Array.isArray(deck) || deck.length < 1 || deck.length > 10000) return 'deck needs 1 to 10000 cards.';
  if (deck.some(v => !Number.isInteger(v) || v < 0 || v >= 10000)) return 'Each card is an integer from 0 to 9999.';
  return null;
}

