function hasGroupsSizeX(deck) {
  const count = new Map();
  for (const card of deck) {
    count.set(card, (count.get(card) || 0) + 1);
  }

  let common = 0;
  for (const frequency of count.values()) {
    let a = common;
    let b = frequency;
    while (b !== 0) {
      const remainder = a % b;
      a = b;
      b = remainder;
    }
    common = a;
  }
  return common >= 2;
}

