function hasGroupsSizeX(deck) {
  const sorted = [...deck].sort((p, q) => p - q);
  const runs = [];
  let i = 0;
  while (i < sorted.length) {
    let j = i;
    while (j < sorted.length && sorted[j] === sorted[i]) j++;
    runs.push(j - i);
    i = j;
  }
  for (let x = 2; x <= deck.length; x++) {
    if (runs.every(r => r % x === 0)) return true;
  }
  return false;
}

