function generate(rand, size) {
  const large = size === 'large';
  const maxValue = 10000;
  const distinct = large ? 1 + Math.floor(rand() * 60) : 1 + Math.floor(rand() * 4);
  const limit = large ? 2000 : 12;
  const values = [];
  while (values.length < distinct) {
    const v = large ? Math.floor(rand() * maxValue) : Math.floor(rand() * 6);
    if (!values.includes(v)) values.push(v);
  }
  const deck = [];
  const mode = Math.floor(rand() * 2);
  if (mode === 0) {
    // Build a deck where every count is a multiple of a shared x >= 2.
    const x = 2 + Math.floor(rand() * (large ? 6 : 3));
    for (const v of values) {
      const room = Math.floor((limit - deck.length) / x);
      if (room < 1) break;
      const copies = x * (1 + Math.floor(rand() * Math.min(room, large ? 8 : 2)));
      for (let k = 0; k < copies; k++) deck.push(v);
    }
    // A rare broken card makes some of these decks fail.
    if (rand() < 0.2 && deck.length < limit) deck.push(values[Math.floor(rand() * values.length)]);
  } else {
    const n = large ? 1000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * limit);
    for (let k = 0; k < n; k++) deck.push(values[Math.floor(rand() * values.length)]);
  }
  if (deck.length === 0) deck.push(values[0]);
  for (let k = deck.length - 1; k > 0; k--) {
    const j = Math.floor(rand() * (k + 1));
    [deck[k], deck[j]] = [deck[j], deck[k]];
  }
  return [deck];
}
